/** Parity: the TypeScript verifier must reproduce the Python verifier on every fixture case.
 *
 * Run: node --experimental-strip-types --test apps/web/tests/
 * verifier-parity.json and the event logs are generated by scripts/export_demo_data.py from
 * the real backend; a backend change that alters any result fails this test until the
 * port is updated to match.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expandLog, roundHalfUp, verifyClaim } from '../src/studio/verifier.ts';

const here = dirname(fileURLToPath(import.meta.url));
const read = (path) => JSON.parse(readFileSync(join(here, path), 'utf8'));
const fixture = read('verifier-parity.json');
const exportData = read('../src/studio/generated/nbr-riv.json');
const sources = {
  canonical: expandLog(read('../src/studio/generated/nbr-riv-events.json')),
  scenario: expandLog(fixture.scenario_events),
  empty: [],
};

test('the fixture covers every verifier outcome', () => {
  const statuses = new Set(fixture.cases.map((c) => c.expected.status));
  assert.deepEqual([...statuses].sort(), ['blocked', 'needs_revision', 'supported_inference', 'verified']);
  assert.ok(fixture.cases.length >= 45);
  const queries = new Set(fixture.cases.map((c) => c.expected.query_id));
  for (const q of ['claim-text-binding-v1', 'evidence-window-v1', 'event-goal-scorer-v1', 'event-sequence-gap-v1']) {
    assert.ok(queries.has(q), q);
  }
});

for (const item of fixture.cases) {
  test(`parity: ${item.name}`, () => {
    const names = item.with_names ? fixture.display_names : null;
    const result = verifyClaim(item.claim, fixture.evidence[item.evidence], sources[item.events], names);
    const { claim_id, ...actual } = result;
    assert.equal(claim_id, item.claim.claim_id);
    assert.deepEqual(actual, item.expected);
  });
}

test('the claims shown on screen are the ones the backend verified', () => {
  const evidence = {
    match_id: exportData.match_id,
    event_ids: sources.canonical.map((e) => e.event_id),
    window: { from_ms: 0, to_ms: exportData.replay_end_ms },
  };
  for (const item of exportData.claims) {
    const { claim_id, ...actual } = verifyClaim(item.claim, evidence, sources.canonical, exportData.display_names);
    assert.deepEqual(actual, item.result, claim_id);
  }
});

test('round half up matches Python decimal rounding of the shortest form', () => {
  const cases = [[0.575, 2, '0.58'], [0.585, 2, '0.59'], [0.5749, 2, '0.57'], [2.5, 0, '3'], [0, 1, '0.0'],
    [0.5795628103277061, 2, '0.58'], [0.995, 2, '1.00'], [1e-7, 6, '0.000000'], [5e-7, 6, '0.000001'], [12, 0, '12']];
  for (const [value, decimals, expected] of cases) assert.equal(roundHalfUp(value, decimals), expected, `${value} @ ${decimals}`);
});

for (const [label, file] of [['overlay cue', 'nbr-riv-overlays.json'], ['fan story', 'nbr-riv-stories.json']]) test(`every ${label} claim re-verifies in the browser with the same verdict`, () => {
  const feed = read(`../src/studio/generated/${file}`);
  const events = sources.canonical;
  const evidence = { match_id: feed.match_id, event_ids: events.map((e) => e.event_id), window: { from_ms: 0, to_ms: feed.replay_end_ms } };
  const byId = new Map(feed.claims.map((c) => [c.claim_id, c]));
  assert.equal(byId.size, feed.claims.length);
  for (const record of feed.claims) {
    const result = verifyClaim(record.claim, evidence, events, exportData.display_names);
    assert.equal(result.status, record.status, record.claim_id);
    assert.equal(result.reason, record.reason, record.claim_id);
    assert.equal(result.observed ?? null, record.observed ?? null, record.claim_id);
    assert.equal(record.claim.text, record.text, record.claim_id);
  }
  for (const cue of feed.cues ?? []) for (const id of cue.claim_ids) assert.ok(byId.has(id), `${cue.cue_id} cites ${id}`);
  for (const story of feed.stories ?? []) for (const check of story.checks) for (const id of check.claim_ids) assert.ok(byId.has(id), `${story.slug} cites ${id}`);
});
